export class DamageSensor extends Sensor {
    /**
     * Events this sensor can emit.
     * @type {string[]}
     * @static
     */
    static events: string[];
    /**
     * Create a new DamageSensor.
     *
     * @param {Object} [config] - Configuration options.
     * @param {number} [config.threatDecayRate=0.1] - Threat decay per second.
     * @param {number} [config.underFireThreshold=2.0] - Seconds to consider "under fire".
     * @param {number} [config.updatePeriod=0.05] - Update interval in seconds.
     */
    constructor(config?: {
        threatDecayRate?: number;
        underFireThreshold?: number;
        updatePeriod?: number;
    });
    /**
     * Threat decay rate per second.
     * @type {number}
     * @private
     */
    private _threatDecayRate;
    /**
     * Seconds threshold for "under fire" status.
     * @type {number}
     * @private
     */
    private _underFireThreshold;
    /**
     * Current threat score.
     * @type {number}
     * @private
     */
    private _threatScore;
    /**
     * Time of last damage event.
     * @type {number}
     * @private
     */
    private _lastDamageTime;
    /**
     * Direction of last damage.
     * @type {{ x: number, y: number, z: number }|null}
     * @private
     */
    private _lastDamageDirection;
    /**
     * Amount of last damage.
     * @type {number}
     * @private
     */
    private _lastDamageAmount;
    /**
     * Queue of pending damage events.
     * @type {Array<{ direction: { x: number, y: number, z: number }, amount: number, time: number }>}
     * @private
     */
    private _damageQueue;
    /**
     * Current time reference.
     * @type {number}
     * @private
     */
    private _currentTime;
    /**
     * Record a damage event.
     * Called externally when the agent takes damage.
     *
     * @param {Object} hitData - Hit information.
     * @param {Object} [hitData.point] - World position of hit.
     * @param {number} [hitData.damage=10] - Damage amount.
     * @param {number} [hitData.shooterIndex] - Index of the shooter body.
     * @param {string} [hitData.shooterType] - Type of the shooter body.
     * @param {Object} body - The agent body that was hit.
     */
    recordDamage(hitData: {
        point?: any;
        damage?: number;
        shooterIndex?: number;
        shooterType?: string;
    }, body: any): void;
    /**
     * Configure sensor parameters.
     *
     * @param {Object} config - Configuration object.
     * @returns {DamageSensor} This instance for chaining.
     */
    set(config: any): DamageSensor;
    /**
     * Reset threat state.
     */
    reset(): void;
}
import { Sensor } from './Sensor.js';
